const shuffle = arr => {
  const list = [...arr];
  for (let i = list.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [list[i], list[j]] = [list[j], list[i]];
  }
  return list;
};

const battleBackgroundQueues = Object.fromEntries(
  Object.entries(battleBackgroundSources).map(([key, list]) => [key, shuffle(list)])
);

const applyBackground = file => {
  const encoded = encodeURI(file);
  document.documentElement.style.setProperty('--page-bg', 'none');
  document.documentElement.style.setProperty('--scene-bg', `url("${encoded}")`);
};

const backgroundPoolKeyForEnemy = enemy => {
  if (!enemy) return 'weak';
  if (enemy.kind === 'oni') return 'boss';
  if (enemy.tier === 'strong') return 'strong';
  if (enemy.tier === 'medium') return 'medium';
  return 'weak';
};

const nextBattleBackgroundForEnemy = enemy => {
  const key = backgroundPoolKeyForEnemy(enemy);
  if (!battleBackgroundQueues[key] || !battleBackgroundQueues[key].length) {
    battleBackgroundQueues[key] = shuffle(battleBackgroundSources[key] || battleBackgroundSources.weak);
  }
  const file = battleBackgroundQueues[key].shift();
  applyBackground(file);
  return file;
};

nextBattleBackgroundForEnemy(null);

