function buildRaceAppearance(reset=false){
 const r=getRace(),rv=raceVisuals[r.name]||raceVisuals.Humano,sel=$('#skinTone'),prev=sel.value,opt=raceCustomOptions[r.name]||raceCustomOptions.Humano;
 sel.innerHTML=rv.skins.map(([v,n])=>`<option value="${v}">${n}</option>`).join('');if(!reset&&rv.skins.some(s=>s[0]===prev))sel.value=prev;else sel.value=rv.skins[Math.min(1,rv.skins.length-1)][0];
 const f=$('#raceFeature'),pat=$('#racePattern'),oldF=f?.value,oldP=pat?.value;if(f){f.innerHTML=opt.features.map(([v,n])=>`<option value="${v}">${n}</option>`).join('');f.value=!reset&&opt.features.some(x=>x[0]===oldF)?oldF:opt.features[0][0]}if(pat){pat.innerHTML=opt.patterns.map(([v,n])=>`<option value="${v}">${n}</option>`).join('');pat.value=!reset&&opt.patterns.some(x=>x[0]===oldP)?oldP:opt.patterns[0][0]}
 const rl=raceLore[r.name]||raceLore.Humano;$('#raceAppearanceNote').innerHTML=`<b>${rl.title}</b> — ${rv.note} ${rl.text} <span class="race-card-traits">${rl.tags.map(t=>`<i>${t}</i>`).join('')}</span>`
}

