const STARTER_ARMOR_IDS={
  'Tanke|normal':'plate_common','Tanke|grande':'large_plate',
  'Paladino|normal':'plate_common','Paladino|grande':'large_plate',
  'Fighter|normal':'plate_common','Fighter|grande':'large_plate',
  'Mago|normal':'arcane_robe','Mago|grande':'large_arcane',
  'Clérigo|normal':'holy_vestment','Clérigo|grande':'large_arcane',
  'Assassino|normal':'light_leather','Assassino|grande':'large_agile',
  'Arqueiro|normal':'ranger_coat','Arqueiro|grande':'large_agile'
};
function starterArmorId(cls,large){return STARTER_ARMOR_IDS[`${cls}|${large?'grande':'normal'}`]||null}
function annotateArmorProgression(){
  const rarityUnlock={Comum:2,Raro:4,Épico:7,Lendário:10};
  armorCatalog.forEach(a=>{
    a.starter=Object.values(STARTER_ARMOR_IDS).includes(a.id);
    if(a.starter){a.unlockAt=0;return}
    if(/^branch_\d+$/.test(a.id)){
      const n=Number(a.id.split('_')[1]);
      a.unlockAt=2+((n-1)%5)*2;
    }else a.unlockAt=a.unlockAt||rarityUnlock[a.rarity]||5;
  });
}
annotateArmorProgression();
function canFindArmor(a,h){
  if(!a||a.starter||!h)return false;
  return a.classes?.includes(h.class)&&(a.adaptive||a.large===h.large)&&(h.wins||0)>=(a.unlockAt||99);
}
function progressionArmorCandidates(h,ownedOnly=true){
  const owned=new Set(h.inventoryArmors||[]);
  return armorCatalog.filter(a=>canFindArmor(a,h)&&(!ownedOnly||!owned.has(a.id)));
}
function awardProgressionArmor(h,force=false){
  const candidates=progressionArmorCandidates(h,true);if(!candidates.length)return null;
  const exact=candidates.filter(a=>a.unlockAt===h.wins);
  const pool=exact.length?exact:candidates;
  const found=pick(pool);h.inventoryArmors.push(found.id);return found;
}

