function weaponAllowedForBuild(w,cls,race,large,bossUnlocked=false){
 if(!w)return false;
 const visibleBoss=!w.bossReward||bossUnlocked;
 const sizeMatch=w.universal||w.adaptive||w.large===large;
 if(cls==='Tanke'){
  // Tanke class equipment is shield-only. The only exception is equipment tied to the selected race.
  const tankShield=w.class==='Tanke'&&importedWeaponFamily(w)==='shield';
  const raceWeapon=w.race===race;
  return visibleBoss&&sizeMatch&&(tankShield||raceWeapon);
 }
 return visibleBoss&&sizeMatch&&(w.class===cls||w.race===race||w.universal===true);
}
function compatibleWeapons(cls=getClass().name,large=getRace().large,race=getRace().name){
 const branch=getBranchName?.()||'',bossUnlocked=!!state.hero?.bossDefeated||!!getUnlockedLegendaryId();
 return weaponCatalog.filter(w=>weaponAllowedForBuild(w,cls,race,large,bossUnlocked)).sort((a,b)=>{
  const rank=w=>w.class===cls?0:(w.universal?1:2);
  const lanceRank=w=>branch==='Lanceiro'&&/Lança/.test(w.name)?-1:0;
  return lanceRank(a)-lanceRank(b)||rank(a)-rank(b)||a.price-b.price;
 })
}
