function weaponCategory(w){
  if(w?.bossReward)return 'Relíquias lendárias';
  const family=(typeof importedWeaponFamily==='function'?importedWeaponFamily(w):'')||w?.weaponType||'',n=(w?.name||'').toLowerCase();
  if(family==='shield'||/escudo/.test(n))return 'Escudos';
  if(family==='hammer'||/martelo|malho|maça|maca|âncora|ancora|quebra-mundos/.test(n))return 'Martelos & maças';
  if(family==='sword'||/espada|lâmina|lamina|montante|gládio|gladio|katana|sabre|rapieira/.test(n))return 'Espadas & lâminas';
  if(/arco|besta|flecha/.test(n))return 'Arcos & distância';
  if(/lança|lanca|alabarda|tridente|haste/.test(n))return 'Lanças & hastes';
  if(/cajado|báculo|baculo|cetro|orbe|códice|codice|grimório|grimorio|obelisco|pilar|agulha|relicário|relicario|turíbulo|turibulo|foco/.test(n))return 'Focos mágicos';
  if(/adaga|punhal|kunai|shuriken|foice|garra/.test(n)||w?.class==='Assassino')return 'Armas leves';
  return 'Outras';
}
