  return new THREE.MeshPhysicalMaterial({color:c,roughness:opts.rough??.26,metalness:opts.metalness??.82,clearcoat:.28,clearcoatRoughness:.22,emissive:opts.emissive?c.clone().multiplyScalar(opts.emissive):0});
