  makePart(g,new THREE.BoxGeometry(.43,.33,.075),plate,[side*.25,.23,-.48],[1,1,1],[0,side*.07,side*.08]);
  detailCurve(g,[[side*.45,.34,-.53],[side*.43,.08,-.54],[side*.31,-.29,-.55]],.016,m.accentMat);
  for(let i=0;i<4;i++)makePart(g,new THREE.SphereGeometry(.018,8,6),m.accentMat,[side*.39,.27-i*.15,-.562]);
