function addArmorSignature(chest,hips,sig,mats){
 const {metalMat,accentMat,auraMat,secondaryMat}=mats;const n=Math.max(1,Number(sig)||1),family=n%10,rank=Math.floor((n-1)/10),depth=.69+.012*(rank%3);
 const gem=(x,y,z=depth,scale=.75)=>makePart(chest,new THREE.OctahedronGeometry(.036,0),auraMat,[x,y,z],[1,1,scale]);
 if(family===1){for(let i=0;i<3+(rank%3);i++){const y=.28-i*.15;makePart(chest,new THREE.BoxGeometry(.11,.075,.042),metalMat,[0,y,depth]);gem((i%2?-1:1)*.18,y+.025,depth+.028,.55)}}
 else if(family===2){for(const side of[-1,1]){detailCurve(chest,[[side*.12,.34,depth],[side*.30,.17,depth+.025],[side*.40,-.07,depth]],.018,accentMat);gem(side*.42,-.08,depth+.025)}}
 else if(family===3){const count=3+(rank%4);for(let i=0;i<count;i++){const x=(i-(count-1)/2)*.13;gem(x,.31-Math.abs(x)*.45,depth+.035,.45);makePart(chest,new THREE.TorusGeometry(.05,.008,6,16),accentMat,[x,-.18+(i%2)*.13,depth+.018],[1,1,1],[Math.PI/2,0,0])}}
 else if(family===4){makePart(chest,new THREE.TorusGeometry(.17+.02*rank,.016,8,28),accentMat,[0,.13,depth+.02],[1,1,1],[Math.PI/2,0,0]);for(const side of[-1,1])makePart(chest,new THREE.ConeGeometry(.035+.006*rank,.20+.02*rank,7),metalMat,[side*(.34+.02*rank),.36,depth],[1,1,1],[0,0,side*.62])}
 else if(family===5){for(let i=0;i<4;i++)detailCurve(chest,[[( -.36+i*.24),.35,depth],[(-.27+i*.18),.06,depth+.03],[(-.36+i*.24),-.28,depth]],.010,auraMat);gem(0,.08,depth+.04,.65)}
 else if(family===6){for(const side of[-1,1])for(let i=0;i<3;i++){const y=.31-i*.24;makePart(chest,new THREE.ConeGeometry(.032,.18+.02*rank,7),accentMat,[side*(.34+.025*i),y,depth+.01],[1,1,1],[0,0,side*.78])}}
 else if(family===7){const count=3+(rank%3);for(let i=0;i<count;i++){const x=(i-(count-1)/2)*.16;makePart(hips,new THREE.BoxGeometry(.13,.18,.06),secondaryMat,[x,-.16-i*.06,.38],[1,1,1],[0,0,(i%2?-.12:.12)])}}
 else if(family===8){const count=3+(rank%3);for(let i=0;i<count;i++){const a=i*Math.PI*2/count;const x=Math.cos(a)*.23,y=.10+Math.sin(a)*.20;gem(x,y,depth+.045,.6)}}
 else if(family===9){const turns=2+(rank%3);for(let i=0;i<turns;i++)detailCurve(chest,[[-.34+i*.18,.31,depth],[0,.18-i*.07,depth+.03],[.34-i*.18,.31,depth]],.008,accentMat)}
 else{for(let i=0;i<5;i++)makePart(chest,new THREE.SphereGeometry(.021,8,6),metalMat,[(i-2)*.13,.37-Math.abs(i-2)*.06,depth+.03],[1,1,.7])}
 makePart(hips,new THREE.OctahedronGeometry(.034,0),rank%2?accentMat:auraMat,[((n%5)-2)*.06,.10,-.51],[1,1,.55]);

}
