 const stance=c.stance||'heroica';
 const strong=['Tanke','Paladino','Fighter'].includes(meta.class),berserker=meta.branch==='Berserker',bulk=(strong?1.22:1)*(berserker?1.18:1)*(c.bodyType==='robusto'?1.10:1);
 const skinShade=animeMaterial(skinMat.color.clone().multiplyScalar(.86),{skin:true});
 const skinDeep=animeMaterial(skinMat.color.clone().multiplyScalar(.72),{skin:true});
 const pose={heroica:{sx:-.08,sy:side<0?.18:-.12,sz:side*.20,ex:-1.08,ez:side*.05,wx:.16,wz:side*.06},defensiva:{sx:-.02,sy:side<0?.10:-.06,sz:side*.30,ex:-1.18,ez:side*.09,wx:.22,wz:side*.10},arcana:{sx:-.18,sy:side<0?.22:-.18,sz:side*.18,ex:-1.00,ez:side*.04,wx:.10,wz:side*.04},furtiva:{sx:.04,sy:side<0?.08:-.12,sz:side*.10,ex:-1.22,ez:side*.12,wx:.20,wz:side*.08}}[stance];
