function makeShieldFaceGeometry(width,height,depth=.10,inset=0){
 const w=Math.max(.18,width-inset),h=Math.max(.28,height-inset*.9);
 const shape=new THREE.Shape(),top=h*.52,bottom=-h*.60,shoulderY=h*.28,waistY=-h*.05,lowerY=-h*.34,sideX=w*.48,waistX=w*.34,lowerX=w*.22;
 shape.moveTo(0,top);
 shape.bezierCurveTo(w*.16,top,w*.36,h*.44,sideX,shoulderY);
 shape.bezierCurveTo(w*.53,h*.08,w*.46,waistY,w*.34,lowerY);
 shape.bezierCurveTo(w*.25,bottom*.28,w*.14,bottom*.06,0,bottom);
 shape.bezierCurveTo(-w*.14,bottom*.06,-w*.25,bottom*.28,-w*.34,lowerY);
 shape.bezierCurveTo(-w*.46,waistY,-w*.53,h*.08,-sideX,shoulderY);
 shape.bezierCurveTo(-w*.36,h*.44,-w*.16,top,0,top);
 const geo=new THREE.ExtrudeGeometry(shape,{depth,steps:1,bevelEnabled:true,bevelSegments:2,bevelSize:Math.min(.025,depth*.35),bevelThickness:Math.min(.018,depth*.28)});
 geo.center();
 return geo
}
