function addWeaponUniqueDetails(weapon,mats,signature=1,weaponName='',slot='primary'){
 if(!weapon)return;const n=Math.max(1,Number(signature)||1),family=n%12,rank=Math.floor((n-1)/12),{metalMat,accentMat,auraMat}=mats,seed=Math.sin(n*12.9898)*43758.5453,offset=(seed-Math.floor(seed))*.16-.08;
 const gem=(x,y,z=.04,s=.55)=>makePart(weapon,new THREE.OctahedronGeometry(.025+.004*(rank%3),0),auraMat,[x,y,z],[1,1,s]);
 if(weapon.userData.weaponType==='bow'){const count=2+(rank%3);for(let i=0;i<count;i++){const y=-.45+i*.30;gem(.045+offset,y,.055,.38);makePart(weapon,new THREE.TorusGeometry(.035+.006*(i%2),.006,6,14),accentMat,[.018+offset,y,.032],[1,1,1],[0,0,.25])}if(rank%2===1)makePart(weapon,new THREE.BoxGeometry(.075,.34,.018),metalMat,[.30,.07,.025],[1,1,1],[0,0,.12])}
 else if(weapon.userData.weaponType==='shield'){const count=4+(rank%3);for(let i=0;i<count;i++){const a=i*Math.PI*2/count,x=Math.cos(a)*.26,y=Math.sin(a)*.26;gem(x,y,.06,.6);makePart(weapon,new THREE.TorusGeometry(.055,.007,6,16),accentMat,[x,y,.055],[1,1,1],[Math.PI/2,0,0])}}
 else if(weapon.userData.weaponType==='hammer'){const y=.68+.12*rank;for(let i=0;i<3+(rank%3);i++){const x=(i-1-(rank%2)*.5)*.12;gem(x,y,.23,.45)}makePart(weapon,new THREE.BoxGeometry(.08,.16,.05),accentMat,[offset,y-.26,.02])}
 else if(weapon.userData.weaponType==='spear'){for(let i=0;i<3;i++)gem(offset,.55+i*.22,.03,.38);if(rank%2===0)detailCurve(weapon,[[-.11,.83,.02],[0,.97,.035],[.11,.83,.02]],.009,auraMat)}
 else if(weapon.userData.weaponType==='axe'){for(let i=0;i<3+(rank%2);i++)makePart(weapon,new THREE.ConeGeometry(.025,.14+.02*rank,7),accentMat,[offset+(i%2?-.13:.13),.62+i*.10,.02],[1,1,1],[0,0,(i%2?-.6:.6)]);gem(0,.82,.04,.5)}
 else if(weapon.userData.weaponType==='dagger'){gem(offset,.43,.045,.55);makePart(weapon,new THREE.TorusGeometry(.055,.008,6,16),accentMat,[0,.25,.02],[1,1,1],[Math.PI/2,0,0]);if(slot==='offhand')makePart(weapon,new THREE.BoxGeometry(.09,.055,.035),metalMat,[0,.60,.02])}
 else if(weapon.userData.weaponType==='staff'){const count=2+(rank%4);for(let i=0;i<count;i++)gem(offset*.5,1.0+i*.08,.10,.42);makePart(weapon,new THREE.TorusGeometry(.06,.009,7,18),accentMat,[0,.84,.03],[1,1,1],[Math.PI/2,0,0])}
 else if(weapon.userData.weaponType==='codex'){for(let i=0;i<3+(rank%3);i++)makePart(weapon,new THREE.BoxGeometry(.07,.018,.018),accentMat,[0,.16+i*.09,.12],[1,1,1],[0,0,(i-rank)*.12]);gem(offset,.42,.18,.7)}
 else if(weapon.userData.weaponType==='orb'){for(let i=0;i<4;i++){const a=i*Math.PI/2;gem(Math.cos(a)*.08,.70+Math.sin(a)*.08,.12,.45)}makePart(weapon,new THREE.TorusGeometry(.105,.010,7,24),accentMat,[0,.70,.08],[1,1,1],[Math.PI/2,0,0])}
 else if(weapon.userData.weaponType==='censer'){for(let i=0;i<3+(rank%3);i++)makePart(weapon,new THREE.SphereGeometry(.018,8,6),auraMat,[Math.cos(i*1.9)*.09,.90+Math.sin(i*1.9)*.05,.13]);makePart(weapon,new THREE.TorusGeometry(.13,.008,7,24),accentMat,[0,.98,.04],[1,1,1],[Math.PI/2,0,0])}
 else{const count=2+(n%4);for(let i=0;i<count;i++){const y=.45+i*.12;gem(offset*(i%2?1:-1),y,.045,.42);if(i<count-1)makePart(weapon,new THREE.TorusGeometry(.028+.006*(i%2),.006,5,14),accentMat,[0,y+.055,.025],[1,1,1],[Math.PI/2,0,0])}if(n%3===0)makePart(weapon,new THREE.ConeGeometry(.035,.20,8),metalMat,[offset,.95,.02],[1,1,1],[0,0,Math.PI/2])}
 weapon.userData.uniqueSignature=n;weapon.userData.uniqueName=weaponName;
}

function addElementalRelicWeapon(hand,mats,{large=false}={}){
 const {metalMat,accentMat,auraMat,secondaryMat}=mats;
 const g=joint(hand,[0,-.02,0],[0,0,-.18]);g.userData.baseRotZ=-.18;g.userData.weaponType='elemental_relic';
 const scale=large?1.16:1;
 makePart(g,new THREE.CylinderGeometry(.055*scale,.075*scale,.55*scale,16),secondaryMat,[0,.22,0]);
 makePart(g,new THREE.TorusGeometry(.18*scale,.022*scale,8,32),metalMat,[0,.55*scale,.02],[1,1,1],[Math.PI/2,0,0]);
 makePart(g,new THREE.OctahedronGeometry(.16*scale,1),auraMat,[0,.78*scale,.05],[1,1,.78]);
 for(const rot of[[0,0,0],[Math.PI/2,0,0],[0,Math.PI/2,0]])makePart(g,new THREE.TorusGeometry(.27*scale,.014*scale,8,34),accentMat,[0,.78*scale,.05],[1,1,1],rot);
 for(const [ang,mat] of [[0,auraMat],[Math.PI*2/3,accentMat],[Math.PI*4/3,metalMat]]){
  const x=Math.cos(ang)*.34*scale,y=.78*scale+Math.sin(ang)*.34*scale;
  makePart(g,new THREE.ConeGeometry(.045*scale,.22*scale,8),mat,[x,y,.07],[1,1,1],[0,0,ang+.55]);
 }
 makePart(g,new THREE.BoxGeometry(.22*scale,.05*scale,.05*scale),accentMat,[0,.30*scale,.05]);
 makePart(g,new THREE.OctahedronGeometry(.055*scale,0),auraMat,[0,.28*scale,.12],[1,1,.52]);
 return g;
}

function addWeaponSet(leftArm,rightArm,chest,c,meta,mats,name=''){
 const leftHand=leftArm?.hand||leftArm,rightHand=rightArm?.hand||rightArm,leftForearm=leftArm?.elbow||leftHand;
 const n=name||'',large=!!meta.large,cls=meta.class,weaponData=weaponCatalog.find(w=>w.name===n);let primary=null,offhand=null;
 if(weaponData?.bossReward&&weaponData.weaponType==='shield'){primary=addImportedShieldWeapon(leftForearm,mats,{large,runic:true,modelKey:c.shieldModel||'auto',weaponData,forearm:true});}
 else if(weaponData?.bossReward){primary=addElementalRelicWeapon(rightHand,mats,{large});}
 else if(cls==='Arqueiro'||/Arco/.test(n)){const r=addBowWeapon(leftHand,rightHand,chest,mats,{large,runic:/Rúnico|Precisão/.test(n),storm:/Tempestade/.test(n),dragon:/Dracônico/.test(n)});primary=r.primary;offhand=r.offhand}
 else if(/Escudo/.test(n)){primary=addImportedShieldWeapon(leftForearm,mats,{large,runic:/Sentinela/.test(n),modelKey:c.shieldModel||'auto',weaponData,forearm:true});if(primary){primary.userData.weaponType='shield';primary.userData.offhandShield=true}}
 else if(/Âncora/.test(n))primary=addAnchorWeapon(rightHand,mats,{large:true})
 else if(/Códice/.test(n)){primary=addCodexWeapon(rightHand,mats,{orb:false});if(primary)primary.userData.weaponType='codex'}
 else if(/Orbe/.test(n)){primary=addCodexWeapon(rightHand,mats,{orb:true});if(primary)primary.userData.weaponType='orb'}
 else if(/Cajado|Obelisco|Pilar|Agulha|Báculo|Cetro|Relicário|Bastão/.test(n)){primary=addStaffWeapon(rightHand,mats,{large,oracle:/Oráculo|Profético/.test(n),voidy:/Vazio|Celeste|Obelisco/.test(n),reliquary:/Relicário/.test(n)});if(primary)primary.userData.weaponType='staff'}
 else if(/Turíbulo/.test(n))primary=addCenserWeapon(rightHand,mats)
 else if(cls==='Assassino'){const opts={large,katar:/Katar/.test(n),axe:/Machadinha/.test(n),scythe:/Foice/.test(n)};primary=addDaggerWeapon(rightHand,mats,{...opts,mirror:false});offhand=addDaggerWeapon(leftHand,mats,{...opts,mirror:true});if(primary)primary.userData.weaponType='dagger';if(offhand)offhand.userData.weaponType='dagger'}
 else if(/Gládio/.test(n))primary=addImportedSwordWeapon(rightHand,mats,{large,holy:cls==='Paladino',dark:false,name:n,modelKey:c.swordModel||'auto',weaponData})
 else if(/Lança/.test(n))primary=addSpearWeapon(rightHand,mats,{large,titan:/Titã/.test(n)})
 else if(/Machado|Labrys/.test(n))primary=addAxeWeapon(rightHand,mats,{large,double:/Labrys/.test(n)})
 else if(/Malho|Martelo|Maça|Quebra-Mundos|Clava/.test(n))primary=addImportedHammerWeapon(rightHand,mats,{large,solar:/Solar|Serafim|Juramento|Sagrado/.test(n),world:/Quebra-Mundos/.test(n),runic:/Rúnic|Relicário|Dracônic/.test(n),modelKey:c.hammerModel||'auto',weaponData})
 else primary=addImportedSwordWeapon(rightHand,mats,{large,holy:cls==='Paladino'||/Consagrada|Aurora|Juramento/.test(n),dark:/Profano|Fantasma/.test(n),name:n,modelKey:c.swordModel||'auto',weaponData});
 if(primary)primary.userData.gripHand='right';
 if(offhand)offhand.userData.gripHand='left';
 const sig=(weaponCatalog.find(w=>w.name===n)||{}).signature||1;if(primary&&!primary.userData.importedFBX)addWeaponUniqueDetails(primary,mats,sig,n,'primary');if(offhand&&!offhand.userData.importedFBX)addWeaponUniqueDetails(offhand,mats,sig+37,n,'offhand');
 // Grip calibration. Long weapons are built along local +Y, while the arm also points back
 // toward the elbow on +Y. They must be flipped at the wrist so the blade/shaft leaves the fist
 // instead of running upward through the forearm.
 const seatInGrip=w=>{if(!w)return;const t=w.userData.weaponType||'';
  if(t==='shield'&&w.userData.forearmMounted){w.position.x-=.01;w.position.y+=.03;w.position.z+=.07;w.userData.forwardLean=1.08;w.userData.gripSeated=true;return}
  const frontByType={sword:.075,spear:.08,dagger:.075,axe:.075,hammer:.075,staff:.07,elemental_relic:.075,censer:.08,bow:.08,orb:.12,codex:.11};
  const yByType={sword:.035,spear:.025,dagger:.03,axe:.03,hammer:.025,staff:.015,elemental_relic:.03,censer:.02,bow:0,orb:.035,codex:.035};
  const leanByType={sword:.0,spear:.015,dagger:.015,axe:.01,hammer:.01,staff:.0,elemental_relic:.01,censer:.02,bow:.02,orb:.05,codex:.05};
  w.position.z+=frontByType[t]??.10;
  w.position.y+=yByType[t]??0;
  w.userData.forwardLean=leanByType[t]??.07;
  w.userData.gripSeated=true;
 };
 seatInGrip(primary);seatInGrip(offhand);
 return {primary,offhand}
}

// Curved horns, stitched leather, facial anatomy and species-specific silhouettes.
function detailCurve(parent,points,radius,mat,taper=false){
 const curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(...p)));
 const geometry=new THREE.TubeGeometry(curve,20,radius,8,false);
 if(taper){const a=geometry.attributes.position;for(let i=0;i<=20;i++){const center=curve.getPointAt(i/20),factor=Math.max(.025,1-i/20);for(let j=0;j<=8;j++){const n=i*9+j;a.setXYZ(n,center.x+(a.getX(n)-center.x)*factor,center.y+(a.getY(n)-center.y)*factor,center.z+(a.getZ(n)-center.z)*factor)}}geometry.computeVertexNormals()}
 return makePart(parent,geometry,mat);
}
