function ensure3D(){
 if(typeof THREE==='undefined')return false;
 if(!viewports.creator)viewports.creator=createViewport('creator3D',{interactive:true});
 if(!viewports.hero)viewports.hero=createViewport('hero3D',{interactive:false});
 if(!viewports.enemy)viewports.enemy=createViewport('enemy3D',{interactive:false,enemy:true});
 return !!viewports.creator
}
function renderMerchant3D(){try{if(!viewports.merchant)viewports.merchant=createViewport('merchant3D',{interactive:true});if(!viewports.merchant||viewports.merchant.contextLost)return false;if(!viewports.merchant.signature){setViewportModel(viewports.merchant,buildMerchantModel());viewports.merchant.signature='rath'}return true}catch(error){console.warn('Modelo do mercador indisponível',error);return false}}
function renderCreator3D(c,meta,wname=''){try{if(!ensure3D()||viewports.creator.contextLost)return false;const model=buildAnimeHeroModel(c,meta,wname);viewports.creator.targetRotY=.18;return setViewportModel(viewports.creator,model)}catch(error){console.warn('Preview 3D indisponível',error);return false}}
function renderBattle3D(h,e,w,a){
 ensure3D();
 const specs=[['hero',JSON.stringify([h.race,h.class,h.branch,h.custom,w?.id,a?.id]),()=>buildAnimeHeroModel(h.custom,{race:h.race,class:h.class,branch:h.branch,large:h.large,equippedArmorId:a?.id||'',equippedArmor:a?.name||'',weaponId:w?.id||''},w?.name||'')],['enemy',[e.name,e.kind,e.tier,e.maxHp].join('|'),()=>buildEnemyModel(e)]];
 for(const [key,signature,build] of specs){const vp=viewports[key];let ok=false;
  try{if(vp&&!vp.contextLost){if(vp.signature!==signature){setViewportModel(vp,build());vp.signature=signature}ok=true}}catch(error){console.warn('Modelo indisponível: '+key,error)}
  $('#'+key+'Frame').classList.toggle('no-webgl',!ok);
 }
 return true;
}

